"""Dopant workflow scaffolding for CatEMC.

Generates the directory structure and scripts for a dopant EMC workflow:
  - generate_initial_population.py
  - calc_factory_nequip.py
  - emc_run_worker_pool.py
  - submit.sh
  - emc_config.yaml (copy of input config)
"""

import os
import textwrap
import shutil

import numpy as np
import yaml


TEMPLATE_YAML = """# CatEMC dopant workflow configuration
# Generated by: catemc setup dopant_workflow

system:
  dopant: Cu
  host_metal: Ru
  dopant_fraction: 0.1
  template_cif: /path/to/RuO2.cif
  supercell: [3, 3, 4]
  structure: bulk  # bulk or surface facet (e.g. 111)

population:
  dopant_valences: [1, 2, 3, 4]
  replicas_per_valence: 4
  temperature_min: 500
  temperature_max: 1000
  num_temperatures: 3  # auto-generated via np.geomspace

preopt:
  model: /path/to/preopt_model.nequip.pt2
  lattice_fmax: 0.05
  optimizer: FIRE

emc:
  model: /path/to/emc_model.nequip.pt2
  total_steps: 5000
  trim_generation: 100
  md_generation: 10
  traj_write_interval: 50
  verbosity: SUMMARY
  fitness:
    fmax_list: [0.10]
    md_timestep_fs: 1.0
    md_taut_fs: 500.0
    md_steps: 200
    md_write_interval: 10
    max_relax_steps: 100
    neighbor_cutoff: 3.5
    raw_score_cutoff: -10000.0

compute:
  gpu_devices: [0]
  workers_per_gpu: auto  # auto = pop_size / 2
  scratch_base: /mnt/scratch
  queue: azure_gpuq
  walltime: "167:00:00"
  project: OER
  vm_size: Standard_NC40ads_H100_v5
  omp_num_threads: 6

environment:
  conda_env: /fs/cephfs/data/qm_inorganics/venvs/nequip-h100
  catemc_source: /fs/cephfs/data/qm_inorganics/sources/CatEMC_sandip/CatEMC
  cuda_home: /fs/cephfs/software/azure9/v2.1/apps/linux-rhel9-zen3/gcc-12.4.0/cuda-12.2.2-4sdxvaer7ivh5k5gmlat6vfrfj6tanpg
  conda_base: /fs/cephfs/data/qm_inorganics/azure-conda/miniforge3
"""


def emit_template(output_path):
    """Write a template YAML config file."""
    with open(output_path, 'w') as f:
        f.write(TEMPLATE_YAML)
    print(f"Template config written to: {output_path}")
    print("Edit the values, then run:")
    print(f"  catemc setup dopant_workflow --input {output_path}")


def scaffold(config_path):
    """Generate the full workflow directory from a config YAML."""
    with open(config_path) as f:
        cfg = yaml.safe_load(f)

    sys_cfg = cfg['system']
    pop_cfg = cfg['population']
    emc_cfg = cfg['emc']
    comp_cfg = cfg['compute']
    env_cfg = cfg['environment']
    preopt_cfg = cfg.get('preopt', {})

    # Resolve relative paths to absolute (relative to config file location)
    config_dir = os.path.dirname(os.path.realpath(config_path))
    def _resolve(p):
        if p and isinstance(p, str) and not os.path.isabs(p):
            return os.path.realpath(os.path.join(config_dir, p))
        return p

    sys_cfg['template_cif'] = _resolve(sys_cfg.get('template_cif'))
    emc_cfg['model'] = _resolve(emc_cfg.get('model'))
    if preopt_cfg:
        preopt_cfg['model'] = _resolve(preopt_cfg.get('model'))
    env_cfg['conda_env'] = _resolve(env_cfg.get('conda_env'))
    env_cfg['catemc_source'] = _resolve(env_cfg.get('catemc_source'))
    env_cfg['cuda_home'] = _resolve(env_cfg.get('cuda_home'))
    env_cfg['conda_base'] = _resolve(env_cfg.get('conda_base'))

    dopant = sys_cfg['dopant']
    host = sys_cfg['host_metal']
    frac = sys_cfg['dopant_fraction']
    structure = sys_cfg['structure']
    comp_name = f"{dopant}{frac}{host}{1 - frac}Ox"

    # Derived values
    temperatures = np.geomspace(
        pop_cfg['temperature_min'],
        pop_cfg['temperature_max'],
        pop_cfg['num_temperatures'],
    ).tolist()
    n_valences = len(pop_cfg['dopant_valences'])
    n_temps = pop_cfg['num_temperatures']
    reps = pop_cfg['replicas_per_valence']
    pop_size = n_valences * n_temps * reps

    if comp_cfg.get('workers_per_gpu') == 'auto' or comp_cfg.get('workers_per_gpu') is None:
        workers_per_gpu = max(1, pop_size // 2)
    else:
        workers_per_gpu = int(comp_cfg['workers_per_gpu'])

    # Create output directory
    out_dir = os.path.join(os.getcwd(), f"{comp_name}/{structure}")
    os.makedirs(out_dir, exist_ok=True)

    # Copy config into output dir
    shutil.copy2(config_path, os.path.join(out_dir, 'emc_config.yaml'))

    # Write all scripts
    _write_generate_pop(out_dir, cfg, dopant, host, frac, structure,
                        temperatures, reps, pop_size, comp_name)
    _write_calc_factory(out_dir, emc_cfg)
    _write_emc_run(out_dir, cfg, dopant, host, structure, comp_name,
                   workers_per_gpu, temperatures, pop_size)
    _write_submit(out_dir, cfg, comp_name, structure, workers_per_gpu)

    if preopt_cfg:
        _write_preopt(out_dir, cfg, dopant, host, structure, comp_name)

    print(f"\nWorkflow scaffolded in: {out_dir}/")
    print(f"  Population size: {pop_size} replicas")
    temps_fmt = [f"{t:.2f}" for t in temperatures]
    print(f"  Temperatures: {temps_fmt}")
    print(f"  Workers per GPU: {workers_per_gpu}")
    print(f"\nNext steps:")
    print(f"  1. cd {out_dir}")
    print(f"  2. python generate_initial_population.py")
    print(f"  3. python preopt_population.py  (if preopt configured)")
    print(f"  4. qsub submit.sh")


def _write_generate_pop(out_dir, cfg, dopant, host, frac, structure,
                        temperatures, reps, pop_size, comp_name):
    sys_cfg = cfg['system']
    pop_cfg = cfg['population']
    supercell = sys_cfg['supercell']
    valences = pop_cfg['dopant_valences']
    host_frac = 1 - frac

    temps_str = repr([round(t, 2) for t in temperatures])
    valences_str = repr(valences)

    script = f'''"""Generate initial population for {comp_name} {structure} EMC."""
from catemc.generate import generate_population
from ase.io import read, write
import numpy as np
import os

# --- Configuration ---
dopant = "{dopant}"
host_metal = "{host}"
dopant_fraction = {frac}
structure = "{structure}"
template_cif = "{sys_cfg['template_cif']}"
supercell = {supercell}

target_metal_species = [dopant, host_metal]
target_metal_composition = {{dopant: dopant_fraction, host_metal: {host_frac}}}
target_nonmetal_species = ["O", "X"]
dopant_valences = {valences_str}
replicas_per_valence = {reps}
temperatures = {temps_str}

cwd = os.path.dirname(os.path.abspath(__file__))
comp_name = f"{{dopant}}{{dopant_fraction}}{{host_metal}}{host_frac}Ox"
system_name = f"{{comp_name}}_{{structure}}"

# --- Build supercell ---
template = read(template_cif)
template *= tuple(supercell)

# Distinguish metal and oxygen atoms
metal_ids, oxygen_ids = [], []
for i, atom in enumerate(template):
    if atom.symbol == "O":
        oxygen_ids.append(i)
    else:
        metal_ids.append(i)
metal_atoms, oxygen_atoms = template[metal_ids], template[oxygen_ids]
sorted_ids = [0] * len(template)
for k, v in enumerate(metal_ids + oxygen_ids):
    sorted_ids[v] = k
bulk = (metal_atoms + oxygen_atoms)[sorted_ids]

# --- Generate population ---
input_pop = []
pop_size_per_valence = len(temperatures) * replicas_per_valence

for dopant_valence in dopant_valences:
    valence_pop = generate_population(
        template=bulk,
        pop_size=pop_size_per_valence,
        target_metal_species=target_metal_species,
        target_metal_composition=target_metal_composition,
        target_nonmetal_species=target_nonmetal_species,
        valences={{dopant: dopant_valence, host_metal: 4, "O": -2}},
    )
    for atoms in valence_pop:
        atoms.info = {{"key_value_pairs": {{}}, "data": {{}}}}
        atoms.info["key_value_pairs"]["dopant_valence"] = dopant_valence
        input_pop.append(atoms)

# --- Assign temperatures and replica indices ---
rep = 0
for xi in range(len(dopant_valences)):
    for T in temperatures:
        for _ in range(replicas_per_valence):
            input_pop[rep].info["key_value_pairs"]["temperature"] = T
            input_pop[rep].info["key_value_pairs"]["replica"] = rep
            input_pop[rep].info["key_value_pairs"]["emc_step"] = 0
            rep += 1

# --- Report ---
for idx, img in enumerate(input_pop):
    kvp = img.info["key_value_pairs"]
    print(f"Replica {{idx}} -> valence={{kvp['dopant_valence']}}, T={{kvp['temperature']:.1f}}")

out_fname = os.path.join(cwd, f"{{system_name}}_input_pop_unrelaxed.traj")
write(out_fname, input_pop)
print(f"\nWritten {{len(input_pop)}} replicas to {{out_fname}}")
'''

    with open(os.path.join(out_dir, 'generate_initial_population.py'), 'w') as f:
        f.write(script)


def _write_calc_factory(out_dir, emc_cfg):
    model = emc_cfg['model']
    script = f'''"""Calculator factory for NequIP worker pool mode.

This module is imported by each persistent worker to load the model ONCE.
The model path can be overridden via calculator_factory_kwargs["model_path"].
"""
import sys
import os
sys.setdlopenflags(os.RTLD_GLOBAL | os.RTLD_NOW)

DEFAULT_MODEL = "{model}"


def create_calculators(model_path=None):
    from nequip.integrations.ase import NequIPCalculator
    path = model_path or DEFAULT_MODEL
    calc = NequIPCalculator.from_compiled_model(path, device="cuda")
    return [calc]
'''

    with open(os.path.join(out_dir, 'calc_factory_nequip.py'), 'w') as f:
        f.write(script)


def _write_emc_run(out_dir, cfg, dopant, host, structure, comp_name,
                   workers_per_gpu, temperatures, pop_size):
    emc_cfg = cfg['emc']
    comp_cfg = cfg['compute']
    fitness = emc_cfg['fitness']
    scratch_base = comp_cfg['scratch_base']
    system_name = f"{comp_name}_{structure}"

    script = f'''"""EMC run script with persistent worker pool mode.

Usage:
    python emc_run_worker_pool.py <gpu_devices> <procs_per_gpu> [traj_write_interval]
    python emc_run_worker_pool.py 0 {workers_per_gpu} {emc_cfg['traj_write_interval']}
"""
import sys
import os

sys.setdlopenflags(os.RTLD_GLOBAL | os.RTLD_NOW)

from catemc.geemc import EMC
from catemc.worker_pool import WorkerPool
from ase.io import read
from ase import units


def main():
    gpu_devices = [int(di) for di in sys.argv[1].split(",")]
    ppg = int(sys.argv[2])
    traj_write_interval = int(sys.argv[3]) if len(sys.argv) > 3 else {emc_cfg['traj_write_interval']}

    os.environ["CUDA_VISIBLE_DEVICES"] = str(gpu_devices[0])

    dopant = "{dopant}"
    structure = "{structure}"
    system_name = "{system_name}"
    dir_name = os.path.dirname(os.path.abspath(__file__))
    scratch_dir = "{scratch_base}/{system_name}"
    input_pop_fname = os.path.join(dir_name, f"{{system_name}}_input_pop.traj")
    target_metal_species = ["{dopant}", "{host}"]
    target_nonmetal_species = ["O", "X"]
    input_pop = read(input_pop_fname, index=":")

    # --- Worker pool setup ---
    fitness_kwargs = {{
        "fmax_list": {repr(fitness['fmax_list'])},
        "target_metal_species": target_metal_species,
        "md_timestep": {fitness['md_timestep_fs']} * units.fs,
        "md_taut": {fitness['md_taut_fs']} * units.fs,
        "md_steps": {fitness['md_steps']},
        "md_write_interval": {fitness['md_write_interval']},
        "max_relax_steps": {fitness['max_relax_steps']},
        "neighbor_cutoff": {fitness['neighbor_cutoff']},
        "raw_score_cutoff": {fitness['raw_score_cutoff']},
        "temperature_key": "temperature",
        "replica_key": "replica",
    }}

    pool = WorkerPool(
        calculator_factory_module="calc_factory_nequip",
        calculator_factory_func="create_calculators",
        calculator_factory_kwargs={{}},
        fitness_func_module="catemc.calculation_templates",
        fitness_func_name="calculate_bulk_fitness_inprocess",
        fitness_kwargs=fitness_kwargs,
        num_workers=ppg,
        gpu_devices=gpu_devices,
        startup_timeout=600.0,
    )
    print(f"Worker pool ready: {{len(input_pop)}} replicas, {{ppg}} workers on GPUs {{gpu_devices}}")

    # --- EMC setup ---
    emc = EMC(system_name,
              calculation_dir=dir_name,
              input_pop=input_pop,
              fix_indices=None,
              trim_generation={emc_cfg['trim_generation']},
              pressure=0.,
              md_generation={emc_cfg['md_generation']},
              exchange_generation=1,
              crossover_rate=0.,
              intraswap_rate=1.,
              metal_element_pool=target_metal_species,
              nonmetal_element_pool=target_nonmetal_species,
              raw_score_cutoff={fitness['raw_score_cutoff']},
              temperature_key="temperature",
              replica_key="replica",
              acceptance_key="accepted",
              category_key="dopant_valence",
              gpu_devices=gpu_devices,
              procs_per_device=ppg,
              worker_pool=pool,
              traj_write_interval=traj_write_interval,
              scratch_dir=scratch_dir,
              verbosity="{emc_cfg['verbosity']}",
              )

    emc.run(total_steps={emc_cfg['total_steps']})
    pool.shutdown()


if __name__ == "__main__":
    main()
'''

    with open(os.path.join(out_dir, 'emc_run_worker_pool.py'), 'w') as f:
        f.write(script)


def _write_submit(out_dir, cfg, comp_name, structure, workers_per_gpu):
    comp_cfg = cfg['compute']
    env_cfg = cfg['environment']

    gpu_str = ','.join(str(g) for g in comp_cfg['gpu_devices'])
    traj_interval = cfg['emc'].get('traj_write_interval', 50)
    omp = comp_cfg.get('omp_num_threads', 6)
    job_name = f"d-{comp_name}_{structure}_EMC"

    script = f'''#!/bin/bash
#PBS -l select=1:ncpus=40:ngpus=1:mem=320gb:mpiprocs=1:ompthreads=1:vm_size={comp_cfg['vm_size']}
#PBS -l walltime={comp_cfg['walltime']}
#PBS -q {comp_cfg['queue']}
#PBS -N {job_name}
#PBS -P {comp_cfg['project']}

module purge
module unuse /gpfs/software/milan9/v2.1/lmod/Core
module use /gpfs/software/azure9/v2.1/lmod/Core
module load gcc/12.4.0 openmpi/4.1.7

export TMPDIR=/fs/cephfs/data/qm_inorganics/venvs/.tmp
mkdir -p $TMPDIR

# CUDA toolkit
export CUDA_HOME={env_cfg['cuda_home']}
export PATH=$CUDA_HOME/bin:$PATH

# GCC runtime (for GLIBCXX_3.4.30)
export LD_PRELOAD=$(dirname $(which g++))/../lib64/libstdc++.so.6

eval "$({env_cfg['conda_base']}/bin/conda shell.bash hook)"
conda activate {env_cfg['conda_env']}

export OMP_NUM_THREADS={omp}
export MKL_NUM_THREADS=1
export OPENBLAS_NUM_THREADS=1
export PYTHONPATH="{env_cfg['catemc_source']}:${{PYTHONPATH}}"

cd $PBS_O_WORKDIR

nvidia-cuda-mps-control -d
python -u emc_run_worker_pool.py {gpu_str} {workers_per_gpu} {traj_interval} >>emc.out 2>emc.err
EXIT_CODE=$?

if [[ $EXIT_CODE -ne 0 && -f .emc_scratch_info ]]; then
    source .emc_scratch_info
    echo "[CRASH-RECOVERY] Python exited with code $EXIT_CODE" >>emc.out
    if [[ -f "$SCRATCH_DB" ]]; then
        cp "$SCRATCH_DB" "${{PERSISTENT_DB%.db}}_recovered.db"
        echo "[CRASH-RECOVERY] Copied $SCRATCH_DB to ${{PERSISTENT_DB%.db}}_recovered.db" >>emc.out
    fi
fi
'''

    submit_path = os.path.join(out_dir, 'submit.sh')
    with open(submit_path, 'w') as f:
        f.write(script)
    os.chmod(submit_path, 0o755)


def _write_preopt(out_dir, cfg, dopant, host, structure, comp_name):
    preopt_cfg = cfg['preopt']
    system_name = f"{comp_name}_{structure}"

    script = f'''"""Pre-optimize the initial population with lattice relaxation."""
import sys
import os
sys.setdlopenflags(os.RTLD_GLOBAL | os.RTLD_NOW)

from ase.io import read, write
from ase.optimize import FIRE
from ase.filters import FrechetCellFilter
from nequip.integrations.ase import NequIPCalculator

MODEL = "{preopt_cfg['model']}"
FMAX = {preopt_cfg.get('lattice_fmax', 0.05)}

def main():
    cwd = os.path.dirname(os.path.abspath(__file__))
    input_fname = os.path.join(cwd, "{system_name}_input_pop_unrelaxed.traj")
    output_fname = os.path.join(cwd, "{system_name}_input_pop.traj")

    calc = NequIPCalculator.from_compiled_model(MODEL, device="cuda")
    input_pop = read(input_fname, index=":")

    for i, atoms in enumerate(input_pop):
        atoms.calc = calc
        fcf = FrechetCellFilter(atoms)
        opt = FIRE(fcf, logfile=None)
        opt.run(fmax=FMAX, steps=500)
        atoms.calc = None
        print(f"  Replica {{i}}: relaxed ({{opt.nsteps}} steps)")

    write(output_fname, input_pop)
    print(f"\nWritten {{len(input_pop)}} pre-optimized replicas to {{output_fname}}")


if __name__ == "__main__":
    main()
'''

    with open(os.path.join(out_dir, 'preopt_population.py'), 'w') as f:
        f.write(script)
